{"path": "/tmp/sv-e5bd856b365141d8bd53d6279e063e51/Components/Pages/Chat.razor", "file_text": "@page "/chat"
@using sv_e5bd856b365141d8bd53d6279e063e51.Services
@using sv_e5bd856b365141d8bd53d6279e063e51.Components.Chat
@inject IChatService ChatService
@rendermode InteractiveServer

<PageTitle>Team Chat</PageTitle>

<div class="chat-layout @(threadOpen ? "thread-open" : "")">
    <ChannelSidebar Channels="channels"
                    ActiveChannelId="activeChannelId"
                    OnChannelSelected="SelectChannel" />

    <MessageArea Channel="activeChannel"
                 Messages="messages"
                 ThreadSummaries="threadSummaries"
                 IsLoadingMore="isLoadingMore"
                 OnOpenThread="OpenThread"
                 OnReact="HandleReaction"
                 OnSendMessage="SendMessage"
                 OnLoadMore="LoadMoreMessages" />

    @if (threadOpen)
    {
        <ThreadPanel RootMessage="threadRootMessage"
                     Replies="threadReplies"
                     OnReply="SendThreadReply"
                     OnClose="CloseThread" />
    }
</div>

@code {
    private List<Channel> channels = [];
    private List<Message> messages = [];
    private List<ThreadSummary> threadSummaries = [];
    private Channel? activeChannel;
    private int activeChannelId;
    private bool threadOpen;
    private Message? threadRootMessage;
    private List<Message> threadReplies = [];
    private bool isLoadingMore;
    private int messageSkip;
    private const int PageSize = 30;

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        activeChannelId = channelId;
        activeChannel = channels.FirstOrDefault(c => c.Id == channelId);
        messageSkip = 0;
        messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        messageSkip = messages.Count;
        threadSummaries = GetThreadSummaries(messages);
        await ChatService.MarkChannelReadAsync(channelId);
        CloseThread();
    }

    private async Task LoadMoreMessages()
    {
        if (isLoadingMore || activeChannel is null) return;
        isLoadingMore = true;
        var older = await ChatService.GetMessagesAsync(activeChannelId, messageSkip, PageSize);
        if (older.Count > 0)
        {
            messages.InsertRange(0, older);
            messageSkip += older.Count;
            threadSummaries = GetThreadSummaries(messages);
        }
        isLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        if (activeChannel is null) return;
        var msg = await ChatService.SendMessageAsync(activeChannelId, content, null);
        messages.Add(msg);
    }

    private async Task OpenThread(int messageId)
    {
        threadRootMessage = messages.FirstOrDefault(m => m.Id == messageId);
        if (threadRootMessage is null) return;
        threadReplies = await ChatService.GetThreadAsync(messageId);
        threadOpen = true;
    }

    private void CloseThread()
    {
        threadOpen = false;
        threadRootMessage = null;
        threadReplies = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (threadRootMessage is null || activeChannel is null) return;
        var reply = await ChatService.SendMessageAsync(activeChannelId, content, threadRootMessage.Id);
        threadReplies.Add(reply);
        // Update thread summary count
        threadSummaries = GetThreadSummaries(messages, threadRootMessage.Id, threadReplies.Count);
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
        // Refresh messages to show updated reactions
        if (activeChannel is not null)
        {
            messages = await ChatService.GetMessagesAsync(activeChannelId, 0, messageSkip);
        }
    }

    private List<ThreadSummary> GetThreadSummaries(List<Message> msgs, int? updatedThreadId = null, int? updatedCount = null)
    {
        var summaries = msgs
            .Where(m => m.ReplyToId is null)
            .Select(m =>
            {
                var replies = msgs.Where(r => r.ReplyToId == m.Id).ToList();
                if (replies.Count == 0 && !(updatedThreadId == m.Id && updatedCount > 0))
                    return null;
                var count = updatedThreadId == m.Id && updatedCount.HasValue ? updatedCount.Value : replies.Count;
                var lastReply = replies.Count > 0 ? replies.Max(r => r.SentAt) : DateTime.UtcNow;
                return new ThreadSummary(m.Id, count, lastReply);
            })
            .Where(s => s is not null)
            .Cast<ThreadSummary>()
            .ToList();
        return summaries;
    }
}
"}

