    display: flex;
    flex-direction: column;
    background: #313338;
    color: #f2f3f5;
    overflow: hidden;
}

::deep .message-area-header {
    padding: 12px 16px;
    border-bottom: 1px solid #1e1f22;
    flex-shrink: 0;
}

::deep .message-area-header h2 {
    margin: 0;
    font-size: 1.1rem;
}

::deep .message-area-header p {
    margin: 4px 0 0;
    font-size: 0.8rem;
    color: #949ba4;
}

::deep .message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px;
    display: flex;
    flex-direction: column;
    gap: 4px;
}

::deep .loading-indicator {
    text-align: center;
    padding: 8px;
    color: #949ba4;
    font-size: 0.85rem;
}

::deep .no-channel-selected {
    display: flex;
    align-items: center;
    justify-content: center;
    flex: 1;
    color: #949ba4;
}

/* Message Bubble */
::deep .message-bubble {
    position: relative;
    padding: 8px 12px;
    border-radius: 6px;
    transition: background 0.15s;
}

::deep .message-bubble:hover {
    background: #2b2d31;
}

::deep .message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

::deep .message-author {
    font-weight: 600;
    font-size: 0.9rem;
    color: #f2f3f5;
}

::deep .message-time {
    font-size: 0.72rem;
    color: #949ba4;
}

::deep .message-content {
    font-size: 0.9rem;
    line-height: 1.4;
    color: #dbdee1;
    word-wrap: break-word;
}

::deep .message-reactions {
    display: flex;
    gap: 4px;
    margin-top: 6px;
    flex-wrap: wrap;
}

::deep .reaction-badge {
    background: #2b2d31;
    border: 1px solid #404249;
    border-radius: 12px;
    padding: 2px 8px;
    font-size: 0.8rem;
    cursor: pointer;
    transition: background 0.15s;
}

::deep .reaction-badge:hover {
    background: #404249;
}

::deep .thread-link {
    margin-top: 4px;
    font-size: 0.8rem;
    color: #00a8fc;
    cursor: pointer;
    font-weight: 500;
}

::deep .thread-link:hover {
    text-decoration: underline;
}

::deep .message-actions {
    position: absolute;
    top: -8px;
    right: 8px;
    display: flex;
    gap: 2px;
    background: #2b2d31;
    border: 1px solid #404249;
    border-radius: 4px;
    padding: 2px;
    z-index: 10;
}

::deep .action-btn {
    background: none;
    border: none;
    color: #b5bac1;
    font-size: 0.75rem;
    padding: 4px 8px;
    border-radius: 3px;
    cursor: pointer;
    white-space: nowrap;
}

::deep .action-btn:hover {
    background: #404249;
    color: #f2f3f5;
}

::deep .emoji-picker {
    position: absolute;
    top: -40px;
    right: 8px;
    background: #2b2d31;
    border: 1px solid #404249;
    border-radius: 6px;
    padding: 6px;
    display: flex;
    gap: 4px;
    z-index: 20;
}

::deep .emoji-option {
    font-size: 1.2rem;
    cursor: pointer;
    padding: 2px 4px;
    border-radius: 4px;
    transition: background 0.15s;
}

::deep .emoji-option:hover {
    background: #404249;
}

/* Message Input */
::deep .message-input {
    display: flex;
    gap: 8px;
    padding: 12px 16px;
    border-top: 1px solid #1e1f22;
    flex-shrink: 0;
}

::deep .message-input textarea {
    flex: 1;
    background: #383a40;
    border: none;
    border-radius: 8px;
    padding: 10px 12px;
    color: #f2f3f5;
    font-size: 0.9rem;
    resize: none;
    outline: none;
    font-family: inherit;
}

::deep .message-input textarea::placeholder {
    color: #6d6f78;
}

::deep .btn-send {
    background: #5865f2;
    color: white;
    border: none;
    border-radius: 8px;
    padding: 8px 16px;
    font-weight: 600;
    font-size: 0.85rem;
    cursor: pointer;
    align-self: flex-end;
    transition: background 0.15s;
}

::deep .btn-send:hover:not(:disabled) {
    background: #4752c4;
}

::deep .btn-send:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* Thread Panel */
::deep .thread-panel {
    background: #2b2d31;
    color: #f2f3f5;
    display: flex;
    flex-direction: column;
    border-left: 1px solid #1e1f22;
    overflow: hidden;
}

::deep .thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 16px;
    border-bottom: 1px solid #1e1f22;
    flex-shrink: 0;
}

::deep .thread-header h3 {
    margin: 0;
    font-size: 1rem;
}

::deep .btn-close-thread {
    background: none;
    border: none;
    color: #b5bac1;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
}

::deep .btn-close-thread:hover {
    background: #404249;
    color: #f2f3f5;
}

::deep .thread-root-message {
    padding: 12px 16px;
    border-bottom: 1px solid #1e1f22;
    background: #232428;
    flex-shrink: 0;
}

::deep .thread-root-message .message-author {
    font-weight: 600;
    font-size: 0.85rem;
}

::deep .thread-root-message .message-content {
    margin-top: 4px;
    font-size: 0.85rem;
    color: #b5bac1;
}

::deep .thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 12px 16px;
    display: flex;
    flex-direction: column;
    gap: 8px;
}

::deep .thread-reply {
    padding: 6px 0;
}

::deep .thread-reply .message-content {
    font-size: 0.85rem;
}
"}

