+@page "/chat"
+@using sv_e5bd856b365141d8bd53d6279e063e51.Services
+@using sv_e5bd856b365141d8bd53d6279e063e51.Components.Chat
+@inject IChatService ChatService
+@rendermode InteractiveServer
+
+<PageTitle>Team Chat</PageTitle>
+
+<div class="chat-layout @(threadOpen ? "thread-open" : "")">
+    <ChannelSidebar Channels="channels"
+                    ActiveChannelId="activeChannelId"
+                    OnChannelSelected="SelectChannel" />
+
+    <MessageArea Channel="activeChannel"
+                 Messages="messages"
+                 ThreadSummaries="threadSummaries"
+                 IsLoadingMore="isLoadingMore"
+                 OnOpenThread="OpenThread"
+                 OnReact="HandleReaction"
+                 OnSendMessage="SendMessage"
+                 OnLoadMore="LoadMoreMessages" />
+
+    @if (threadOpen)
+    {
+        <ThreadPanel RootMessage="threadRootMessage"
+                     Replies="threadReplies"
+                     OnReply="SendThreadReply"
+                     OnClose="CloseThread" />
+    }
+</div>
+
+@code {
+    private List<Channel> channels = [];
+    private List<Message> messages = [];
+    private List<ThreadSummary> threadSummaries = [];
+    private Channel? activeChannel;
+    private int activeChannelId;
+    private bool threadOpen;
+    private Message? threadRootMessage;
+    private List<Message> threadReplies = [];
+    private bool isLoadingMore;
+    private int messageSkip;
+    private const int PageSize = 30;
+
+    protected override async Task OnInitializedAsync()
+    {
+        channels = await ChatService.GetChannelsAsync();
+        if (channels.Count > 0)
+        {
+            await SelectChannel(channels[0].Id);
+        }
+    }
+
+    private async Task SelectChannel(int channelId)
+    {
+        activeChannelId = channelId;
+        activeChannel = channels.FirstOrDefault(c => c.Id == channelId);
+        messageSkip = 0;
+        messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
+        messageSkip = messages.Count;
+        threadSummaries = GetThreadSummaries(messages);
+        await ChatService.MarkChannelReadAsync(channelId);
+        CloseThread();
+    }
+
+    private async Task LoadMoreMessages()
+    {
+        if (isLoadingMore || activeChannel is null) return;
+        isLoadingMore = true;
+        var older = await ChatService.GetMessagesAsync(activeChannelId, messageSkip, PageSize);
+        if (older.Count > 0)
+        {
+            messages.InsertRange(0, older);
+            messageSkip += older.Count;
+            threadSummaries = GetThreadSummaries(messages);
+        }
+        isLoadingMore = false;
+    }
+
+    private async Task SendMessage(string content)
+    {
+        if (activeChannel is null) return;
+        var msg = await ChatService.SendMessageAsync(activeChannelId, content, null);
+        messages.Add(msg);
+    }
+
+    private async Task OpenThread(int messageId)
+    {
+        threadRootMessage = messages.FirstOrDefault(m => m.Id == messageId);
+        if (threadRootMessage is null) return;
+        threadReplies = await ChatService.GetThreadAsync(messageId);
+        threadOpen = true;
+    }
+
+    private void CloseThread()
+    {
+        threadOpen = false;
+        threadRootMessage = null;
+        threadReplies = [];
+    }
+
+    private async Task SendThreadReply(string content)
+    {
+        if (threadRootMessage is null || activeChannel is null) return;
+        var reply = await ChatService.SendMessageAsync(activeChannelId, content, threadRootMessage.Id);
+        threadReplies.Add(reply);
+        // Update thread summary count
+        threadSummaries = GetThreadSummaries(messages, threadRootMessage.Id, threadReplies.Count);
+    }
+
+    private async Task HandleReaction((int MessageId, string Emoji) args)
+    {
+        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
+        // Refresh messages to show updated reactions
+        if (activeChannel is not null)
+        {
+            messages = await ChatService.GetMessagesAsync(activeChannelId, 0, messageSkip);
+        }
+    }
+
+    private List<ThreadSummary> GetThreadSummaries(List<Message> msgs, int? updatedThreadId = null, int? updatedCount = null)
+    {
+        var summaries = msgs
+            .Where(m => m.ReplyToId is null)
+            .Select(m =>
+            {
+                var replies = msgs.Where(r => r.ReplyToId == m.Id).ToList();
+                if (replies.Count == 0 && !(updatedThreadId == m.Id && updatedCount > 0))
+                    return null;
+                var count = updatedThreadId == m.Id && updatedCount.HasValue ? updatedCount.Value : replies.Count;
+                var lastReply = replies.Count > 0 ? replies.Max(r => r.SentAt) : DateTime.UtcNow;
+                return new ThreadSummary(m.Id, count, lastReply);
+            })
+            .Where(s => s is not null)
+            .Cast<ThreadSummary>()
+            .ToList();
+        return summaries;
+    }
+}
+

toolArgs.file_text:
.chat-layout {
    display: grid;
    grid-template-columns: 20% 1fr;
    height: 100vh;
    overflow: hidden;
}

.chat-layout.thread-open {
    grid-template-columns: 20% 1fr 25%;
}

/* Channel Sidebar */
::deep .channel-sidebar {
    background: #2b2d31;
    color: #f2f3f5;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #1e1f22;
    overflow: hidden;
}

::deep .sidebar-header {
    padding: 16px;
    border-bottom: 1px solid #1e1f22;
}

::deep .sidebar-header h3 {
    margin: 0;
    font-size: 1rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: #b5bac1;
}

::deep .channel-list {
    overflow-y: auto;
    flex: 1;
    padding: 8px 0;
}

::deep .channel-item {
    padding: 8px 16px;
    cursor: pointer;
    border-radius: 4px;
    margin: 0 8px;
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 4px;
    transition: background 0.15s;
}

::deep .channel-item:hover {
    background: #35373c;
}

::deep .channel-item.active {
    background: #404249;
}

::deep .channel-name {
    font-weight: 600;
    font-size: 0.95rem;
    flex: 1;
}

::deep .channel-description {
    width: 100%;
    font-size: 0.75rem;
    color: #949ba4;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

::deep .unread-badge {
    background: #f23f43;
    color: white;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 2px 6px;
    border-radius: 10px;
    min-width: 18px;
    text-align: center;
}

/* Message Area */
::deep .message-area {
    display: flex;
    flex-direction: column;
    background: #313338;
    color: #f2f3f5;
    overflow: hidden;
}

::deep .message-area-header {
    padding: 12px 16px;
    border-bottom: 1px solid #1e1f22;
    flex-shrink: 0;
}

::deep .message-area-header h2 {
    margin: 0;
    font-size: 1.1rem;
}

::deep .message-area-header p {
    margin: 4px 0 0;
    font-size: 0.8rem;
    color: #949ba4;
}

::deep .message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px;
    display: flex;
    flex-direction: column;
    gap: 4px;
}

::deep .loading-indicator {
    text-align: center;
    padding: 8px;
    color: #949ba4;
    font-size: 0.85rem;
}

::deep .no-channel-selected {
    display: flex;
    align-items: center;
    justify-content: center;
    flex: 1;
    color: #949ba4;
}

/* Message Bubble */
::deep .message-bubble {
    position: relative;
    padding: 8px 12px;
    border-radius: 6px;
    transition: background 0.15s;
}

::deep .message-bubble:hover {
    background: #2b2d31;
}

::deep .message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 2px;
}

::deep .message-author {
    font-weight: 600;
    font-size: 0.9rem;
    color: #f2f3f5;
}

::deep .message-time {
    font-size: 0.72rem;
    color: #949ba4;
}

::deep .message-content {
    font-size: 0.9rem;
    line-height: 1.4;
    color: #dbdee1;
    word-wrap: break-word;
}

::deep .message-reactions {
    display: flex;
    gap: 4px;
    margin-top: 6px;
    flex-wrap: wrap;
}

::deep .reaction-badge {
    background: #2b2d31;
    border: 1px solid #404249;
    border-radius: 12px;
    padding: 2px 8px;
    font-size: 0.8rem;
    cursor: pointer;
    transition: background 0.15s;
}

::deep .reaction-badge:hover {
    background: #404249;
}

::deep .thread-link {
    margin-top: 4px;
    font-size: 0.8rem;
    color: #00a8fc;
    cursor: pointer;
    font-weight: 500;
}

::deep .thread-link:hover {
    text-decoration: underline;
}

::deep .message-actions {
    position: absolute;
    top: -8px;
    right: 8px;
    display: flex;
    gap: 2px;
    background: #2b2d31;
    border: 1px solid #404249;
    border-radius: 4px;
    padding: 2px;
    z-index: 10;
}

::deep .action-btn {
    background: none;
    border: none;
    color: #b5bac1;
    font-size: 0.75rem;
    padding: 4px 8px;
    border-radius: 3px;
    cursor: pointer;
    white-space: nowrap;
}

::deep .action-btn:hover {
    background: #404249;
    color: #f2f3f5;
}

::deep .emoji-picker {
    position: absolute;
    top: -40px;
    right: 8px;
    background: #2b2d31;
    border: 1px solid #404249;
    border-radius: 6px;
    padding: 6px;
    display: flex;
    gap: 4px;
    z-index: 20;
}

::deep .emoji-option {
    font-size: 1.2rem;
    cursor: pointer;
    padding: 2px 4px;
    border-radius: 4px;
    transition: background 0.15s;
}

::deep .emoji-option:hover {
    background: #404249;
}

/* Message Input */
::deep .message-input {
    display: flex;
    gap: 8px;
    padding: 12px 16px;
    border-top: 1px solid #1e1f22;
    flex-shrink: 0;
}

::deep .message-input textarea {
    flex: 1;
    background: #383a40;
    border: none;
    border-radius: 8px;
    padding: 10px 12px;
    color: #f2f3f5;
    font-size: 0.9rem;
    resize: none;
    outline: none;
    font-family: inherit;
}

::deep .message-input textarea::placeholder {
    color: #6d6f78;
}

::deep .btn-send {
    background: #5865f2;
    color: white;
    border: none;
    border-radius: 8px;
    padding: 8px 16px;
    font-weight: 600;
    font-size: 0.85rem;
    cursor: pointer;
    align-self: flex-end;
    transition: background 0.15s;
}

::deep .btn-send:hover:not(:disabled) {
    background: #4752c4;
}

::deep .btn-send:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* Thread Panel */
::deep .thread-panel {
    background: #2b2d31;
    color: #f2f3f5;
    display: flex;
    flex-direction: column;
    border-left: 1px solid #1e1f22;
    overflow: hidden;
}

::deep .thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 16px;
    border-bottom: 1px solid #1e1f22;
    flex-shrink: 0;
}

::deep .thread-header h3 {
    margin: 0;
    font-size: 1rem;
}

::deep .btn-close-thread {
    background: none;
    border: none;
    color: #b5bac1;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
}

::deep .btn-close-thread:hover {
    background: #404249;
    color: #f2f3f5;
}

::deep .thread-root-message {
    padding: 12px 16px;
    border-bottom: 1px solid #1e1f22;
    background: #232428;
    flex-shrink: 0;
}

::deep .thread-root-message .message-author {
    font-weight: 600;
    font-size: 0.85rem;
}

::deep .thread-root-message .message-content {
    margin-top: 4px;
    font-size: 0.85rem;
    color: #b5bac1;
}

::deep .thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 12px 16px;
    display: flex;
    flex-direction: column;
    gap: 8px;
}

::deep .thread-reply {
    padding: 6px 0;
}

::deep .thread-reply .message-content {
    font-size: 0.85rem;
}

